using WTelegram;
using WTelegram.Client;

namespace TelegramChannelListener
{
    class Program
    {
        private static string ApiHash = "YOUR_API_HASH";
        private static int ApiId = YOUR_API_ID;
        private static string ChannelUsername = "@channelusername";

        static async Task Main(string[] args)
        {
            MyTelegramClient client = new MyTelegramClient(ChannelUsername);

            if (!await client.Authenticate(ApiId, ApiHash))
            {
                Console.WriteLine("Failed to authenticate. Please ensure that the API credentials are correct.");
                return;
            }

            Console.WriteLine("Authenticated. Listening for messages...");
            await client.Run();
        }
    }

    class MyTelegramClient : TelegramClient
    {
        private string _channelUsername;

        public MyTelegramClient(string channelUsername) : base()
        {
            _channelUsername = channelUsername;
        }

        protected override async Task ProcessUpdates(TL.Updates updates)
        {
            foreach (var update in updates.Updates)
            {
                if (update is TL.UpdateNewChannelMessage channelMessage && channelMessage.Message is TL.Message message)
                {
                    var channel = await GetEntityAsync<TL.Channel>(_channelUsername);
                    if (channel.Id == message.ToId.ChannelId)
                    {
                        // Display the message
                        Console.WriteLine($"Message from {_channelUsername}: {message.Message}");
                    }
                }
            }

            await base.ProcessUpdates(updates);
        }
    }
}
