        if (MapUtils.isEmpty(operatorTicketNum)){
            return null;
        }
        //遍历找到map中的最小值
        int leastNum = Integer.MAX_VALUE;
        Set<Map.Entry<String, Integer>> entries = operatorTicketNum.entrySet();
        Iterator<Map.Entry<String, Integer>> iterator = entries.iterator();
        while (iterator.hasNext()){
            Map.Entry<String, Integer> curEntry = iterator.next();
            int curNum = Integer.MAX_VALUE;
            try {
                curNum = curEntry.getValue().intValue();
            } catch (Exception e) {
                qcLog.warn("getLeastOperatorsFromMap,e:", e);
            }
            if (curNum < leastNum){
                leastNum = curNum;
            }
        }
        //将最小值的key都放到结果里面
