In order to read messages from a public Telegram channel you're not an admin of, you can use the `TLSharp` library. You can install it via NuGet.

Here's a code example of how to use the `TLSharp` library to do that:

1. First, register your application to get the API ID and API Hash on the [Telegram website](https://my.telegram.org/auth).

2. Replace *API_ID* and *API_HASH* with your relevant values and subscribe to channels from which you intend to read messages.

3. Use this code to listen for incoming messages in the specified public Telegram channel:

```csharp
using System;
using System.Linq;
using System.Threading.Tasks;
using TLSharp.Core;

namespace TelegramChannelListener
{
    class Program
    {
        private const int API_ID = YOUR_API_ID; // Replace with your API ID
        private const string API_HASH = "YOUR_API_HASH"; // Replace with your API Hash
        private const string PHONE_NUMBER = "YOUR_PHONE_NUMBER"; // Replace with your phone number

        static async Task Main(string[] args)
        {
            var client = NewAuthentication();

            var user = await client.MakeAuthAsync(PHONE_NUMBER);
            Console.WriteLine("Connected, welcome " + user.name);

            var targetChannel = "examplechannel"; // Replace with the public channel's username you want to listen to

            while (true)
            {
                try
                {
-                   var result = await ReadMessagesAsync(client, targetChannel);
                    if (result)
                        break;
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error: " + ex.Message);
                    await Task.Delay(TimeSpan.FromSeconds(1));
                }
            }
        }

        private static TelegramClient NewAuthentication()
        {
            var client = new TelegramClient(API_ID, API_HASH);
            client.ConnectAsync().Wait();

            if (!client.IsUserAuthorized())
            {
                Console.WriteLine("You need to sign in to your Telegram account to proceed.");
                client.SendCodeRequestAsync(PHONE_NUMBER).Wait();

                Console.WriteLine("Enter the verification code sent to your mobile phone:");
                var code = Console.ReadLine();

                client.MakeAuthAsync(PHONE_NUMBER, code).Wait();
            }

            return client;
        }

        private static async Task<bool> ReadMessagesAsync(TelegramClient client, string targetChannel)
        {
            var dialogs = await client.GetUserDialogsAsync();

            var chat = dialogs.Chats
                .OfType<TLSharp.Core.Types.TLChannel>()
                .FirstOrDefault(c => c.username == targetChannel);

            if (chat == null)
            {
                Console.WriteLine("Couldn't find the public channel: @" + targetChannel);
                return true;
            }

            Console.WriteLine("Listening for new messages in @" + targetChannel);

            var messages = await client.GetMessagesAsync(chat);
            var lastId = messages.Select(m => (m as TLSharp.Core.Types.TLMessage)?.id ?? 0).Max();
            var count = 0;
            while (true)
            {
                var newMessages = await client.GetMessagesAsync(chat);
                var currentId = newMessages.Select(m => (m as TLSharp.Core.Types.TLMessage)?.id ?? 0).Max();

                if (currentId > lastId)
                {
                    foreach (var m in newMessages)
                    {
                        if (m is TLSharp.Core.Types.TLMessage)
                        {
                            Console.WriteLine("New message: " + (m as TLSharp.Core.Types.TLMessage)?.message);
                        }
                    }
                    count++;
                }

                if (count > 100)
                {
-                  lastId = currentId;
                    count = 0;
                }
                await Task.Delay(TimeSpan.FromSeconds(1));
            }
        }
    }
}
```

Keep in mind that the `TLSharp` library is not officially supported by Telegram, and might have limitations. Also, note that this example is for educational purposes and might not be suitable for use in production. Don't forget to add proper error handling and rate-limiting to avoid hitting API restrictions.

