function multiply_matrices($a, $b) {
  $rows_a = count($a);
  $cols_a = count($a[0]);

  $rows_b = count($b);
  $cols_b = count($b[0]);

  if ($cols_a != $rows_b) {
    return "Matrices cannot be multiplied, number of columns in A must match number of rows in B";
  }

  $result = array();

  for ($i = 0; $i < $rows_a; $i++) {
    $row = array();

    for ($j = 0; $j < $cols_b; $j++) {
