```cpp
#include <algorithm>
#include <cfloat>
#include <cmath>

class SimpleRayTracer
{
public:
  SimpleRayTracer(unsigned int MaxDepth) : maxDepth(MaxDepth) {}

  void traceScene(const Scene &sceneModel, RGBImage &image)
  {
    Camera camera(-8, 1, 1, 0.75, 640, 480);

    for (unsigned int y = 0; y < image.height(); y++)
    {
      for (unsigned int x = 0; x < image.width(); x++)
      {
        Vector rayDirection = camera.generateRay(x, y);
        Color color = trace(sceneModel, camera.Position(), rayDirection, 0);
        image.setPixelColor(x, y, color);
      }
    }
  }

protected:
  Color trace(const Scene &sceneModel, const Vector &o, const Vector &d, int depth)
  {
    if (depth >= maxDepth)
      return Color(0, 0, 0);

    float t_near = FLT_MAX;
    const Triangle *hitTriangle = nullptr;

    /* Find the closest triangle */
    for (unsigned int i = 0; i < sceneModel.getTriangleCount(); ++i)
    {
      const Triangle &triangle = sceneModel.getTriangle(i);
      float t;
      if (o.triangleIntersection(d, triangle.A, triangle.B, triangle.C, t))
      {
        if (t < t_near)
        {
          t_near = t;
          hitTriangle = &triangle;
        }
      }
    }

    if (!hitTriangle)
      return Color(0, 0, 0);

    Vector surfacePoint = o + d * t_near;
    Vector normal = hitTriangle->calcNormal(surfacePoint);
    normal.normalize();
    Vector eye = -d;

    /* Calculate local illumination */
    Color color = localIllumination(surfacePoint, eye, normal, sceneModel.getLight(0), hitTriangle->getMaterial());

    /* Calculate reflection */
    if (depth < maxDepth - 1 && hitTriangle->getMaterial().getReflectivity(surfacePoint) > 0)
    {
      Vector reflectionDirection = d.reflection(normal);
      Color reflectedColor = trace(sceneModel, surfacePoint, reflectionDirection, depth + 1);
      color += reflectedColor * hitTriangle->getMaterial().getReflectivity(surfacePoint);
    }

    return color;
  }

  Color localIllumination(const Vector &surfacePoint, const Vector &eye, const Vector &normal, const PointLight &light, const Material &material)
  {
    // Currently, only the diffuse component is returned.
    return material.getDiffuseCoeff(surfacePoint);
  }

private:
  int maxDepth;
};
```

